// Extract contacts from Odoo response and prepare for validation
const response = $input.item.json;

if (!response.result || !Array.isArray(response.result)) {
  throw new Error('Invalid Odoo response: ' + JSON.stringify(response));
}

const contacts = response.result;
const today = new Date();
const thirtyDaysAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);

// Filter contacts that need verification
const contactsToVerify = contacts.filter(contact => {
  // Skip if verified within last 30 days
  if (contact.x_last_verified) {
    const lastVerified = new Date(contact.x_last_verified);
    if (lastVerified > thirtyDaysAgo) {
      return false;
    }
  }

  // Must have a parent company
  if (!contact.parent_id) {
    return false;
  }

  return true;
}).map(contact => ({
  odoo_id: contact.id,
  name: contact.name,
  email: contact.email || '',
  job_title: contact.function || '',
  company_id: contact.parent_id[0],
  company_name: contact.parent_id[1],
  linkedin_url: contact.x_linkedin_url || '',
  last_verified: contact.x_last_verified,
  current_status: contact.x_verification_status || 'unverified'
}));

// Return limited batch (respect API quota)
const DAILY_LIMIT = 50;
const batch = contactsToVerify.slice(0, DAILY_LIMIT);

if (batch.length === 0) {
  return {
    json: {
      message: 'No contacts need verification today',
      total_contacts: contacts.length,
      batch_size: 0
    }
  };
}

return batch.map(contact => ({ json: contact }));

// Validate contact employment status
const contact = $('Rate Limit (5s)').item.json;
const linkedinResponse = $input.item.json;

let verificationResult = {
  odoo_id: contact.odoo_id,
  name: contact.name,
  company_name: contact.company_name,
  linkedin_url: contact.linkedin_url,
  status: 'unable_to_verify',
  confidence: 0,
  notes: '',
  current_company_linkedin: '',
  new_job_title: '',
  verified_at: new Date().toISOString()
};

// Check for API errors
if (linkedinResponse.statusCode && linkedinResponse.statusCode !== 200) {
  verificationResult.notes = `API Error: ${linkedinResponse.statusCode}`;
  return { json: verificationResult };
}

const profile = linkedinResponse.body || linkedinResponse;

if (!profile || !profile.experiences) {
  verificationResult.notes = 'No experience data found';
  return { json: verificationResult };
}

// Find current job (most recent experience without end date)
const currentJobs = (profile.experiences || []).filter(exp => {
  return exp.ends_at === null || exp.ends_at === undefined;
});

if (currentJobs.length === 0) {
  verificationResult.status = 'left_company';
  verificationResult.notes = 'No current employment found';
  verificationResult.confidence = 80;
  return { json: verificationResult };
}

// Check if any current job matches our company
const companyNameNormalized = contact.company_name.toLowerCase()
  .replace(/\s+(inc|llc|ltd|corp|corporation|gmbh|ag|sa|srl)[\.\s]*$/i, '')
  .trim();

let matchFound = false;
let currentCompanyNames = [];

for (const job of currentJobs) {
  const linkedinCompany = (job.company || '').toLowerCase()
    .replace(/\s+(inc|llc|ltd|corp|corporation|gmbh|ag|sa|srl)[\.\s]*$/i, '')
    .trim();

  currentCompanyNames.push(job.company);

  // Check for match (exact or partial)
  if (linkedinCompany === companyNameNormalized ||
      linkedinCompany.includes(companyNameNormalized) ||
      companyNameNormalized.includes(linkedinCompany)) {
    matchFound = true;
    verificationResult.current_company_linkedin = job.company;
    verificationResult.new_job_title = job.title || '';
    break;
  }
}

if (matchFound) {
  verificationResult.status = 'verified';
  verificationResult.confidence = 95;
  verificationResult.notes = `Confirmed: Still at ${verificationResult.current_company_linkedin}`;
  if (verificationResult.new_job_title && 
      verificationResult.new_job_title !== contact.job_title) {
    verificationResult.notes += `. Title changed: ${contact.job_title} → ${verificationResult.new_job_title}`;
  }
} else {
  verificationResult.status = 'left_company';
  verificationResult.confidence = 90;
  verificationResult.current_company_linkedin = currentCompanyNames.join(', ');
  verificationResult.notes = `No longer at ${contact.company_name}. Current: ${currentCompanyNames.join(', ')}`;
}

return { json: verificationResult };

// Try to find person at company without LinkedIn URL
const contact = $('Rate Limit (5s)1').item.json;
const searchResponse = $input.item.json;

let verificationResult = {
  odoo_id: contact.odoo_id,
  name: contact.name,
  company_name: contact.company_name,
  linkedin_url: '',
  status: 'unable_to_verify',
  confidence: 0,
  notes: 'No LinkedIn URL - searched by name',
  current_company_linkedin: '',
  new_job_title: '',
  verified_at: new Date().toISOString()
};

// Check for API errors
if (searchResponse.statusCode && searchResponse.statusCode !== 200) {
  verificationResult.notes = `Search API Error: ${searchResponse.statusCode}`;
  return { json: verificationResult };
}

const results = searchResponse.body?.employees || searchResponse.employees || [];

if (results.length === 0) {
  verificationResult.notes = `No matches found for "${contact.name}" at "${contact.company_name}"`;
  return { json: verificationResult };
}

// Find best match by name similarity
const contactNameParts = contact.name.toLowerCase().split(/\s+/);

for (const employee of results) {
  const employeeName = (employee.profile?.full_name || '').toLowerCase();
  const matchScore = contactNameParts.filter(part => 
    employeeName.includes(part)
  ).length / contactNameParts.length;

  if (matchScore >= 0.8) { // 80% name match
    verificationResult.status = 'verified';
    verificationResult.confidence = 85;
    verificationResult.linkedin_url = employee.profile?.public_identifier 
      ? `https://linkedin.com/in/${employee.profile.public_identifier}`
      : '';
    verificationResult.current_company_linkedin = contact.company_name;
    verificationResult.new_job_title = employee.profile?.headline || '';
    verificationResult.notes = `Found match: ${employee.profile?.full_name}. LinkedIn URL discovered.`;
    break;
  }
}

if (verificationResult.status === 'unable_to_verify') {
  verificationResult.notes = `No strong name match found. Best results: ${results.slice(0, 3).map(e => e.profile?.full_name).join(', ')}`;
  verificationResult.confidence = 30;
}

return { json: verificationResult };

// Collect all results for summary report
const allResults = $input.all();

const summary = {
  total_processed: allResults.length,
  verified: 0,
  left_company: 0,
  unable_to_verify: 0,
  linkedin_urls_discovered: 0,
  title_changes: 0,
  details: []
};

for (const item of allResults) {
  const result = item.json;

  switch (result.status) {
    case 'verified':
      summary.verified++;
      break;
    case 'left_company':
      summary.left_company++;
      break;
    default:
      summary.unable_to_verify++;
  }

  if (result.notes && result.notes.includes('LinkedIn URL discovered')) {
    summary.linkedin_urls_discovered++;
  }

  if (result.notes && result.notes.includes('Title changed')) {
    summary.title_changes++;
  }

  summary.details.push({
    name: result.name,
    company: result.company_name,
    status: result.status,
    confidence: result.confidence,
    notes: result.notes
  });
}

summary.run_date = new Date().toISOString();
summary.report = `
# Contact Validation Report
Date: ${new Date().toLocaleDateString()}

## Summary
- Total Processed: ${summary.total_processed}
- ✅ Verified (Still Employed): ${summary.verified}
- ⚠️ Left Company: ${summary.left_company}
- ❓ Unable to Verify: ${summary.unable_to_verify}
- 🔗 LinkedIn URLs Discovered: ${summary.linkedin_urls_discovered}
- 📝 Title Changes Detected: ${summary.title_changes}

## Actions Required
- Review ${summary.left_company} contacts who may have left their companies
- Update ${summary.unable_to_verify} contacts with missing information
`;

return { json: summary };
